<script setup lang="ts">
import { computed } from 'vue'
const props = defineProps<{ chat:any; coverUrl:string; displayName:string; displaySignature:string; moments:any[]; loading:boolean; canViewMoments:boolean }>()
const emit = defineEmits<{ (event:'open-moments'):void; (event:'copy-id'):void }>()
const photoMoments = computed(() => props.moments.flatMap(moment => { const image=Array.isArray(moment.images)?moment.images[0]:null; return image?[{...moment,previewImage:typeof image==='string'?image:image.url}]:[] }).filter(item=>item.previewImage).slice(0,3))
const slots = computed(() => Array.from({length:3},(_,index)=>photoMoments.value[index]||null))
const formatDate=(timestamp:number)=>new Date(timestamp).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'}).replace('/','.')
</script>

<template>
  <section class="profile-letter">
    <header class="profile-letter__hero"><div class="profile-letter__photo-sheet"><img v-if="coverUrl" :src="coverUrl" alt="角色主页封面" /><div v-else></div></div><img v-if="chat.avatarUrl" class="profile-letter__avatar" :src="chat.avatarUrl" alt="角色头像" /><span v-else class="profile-letter__avatar fallback">{{ displayName.charAt(0) }}</span></header>
    <main class="profile-letter__body"><section class="profile-letter__identity"><p>PRIVATE NOTE</p><h1>{{ displayName }}</h1><button v-if="chat.socialProfile?.socialId" type="button" @click="emit('copy-id')">@{{ chat.socialProfile.socialId }}</button><i></i><small>她留下的话</small><blockquote>{{ displaySignature }}</blockquote></section>
      <section v-if="canViewMoments" class="profile-letter__album"><header><span>相册碎片</span><span>/ {{ String(moments.length).padStart(2,'0') }}</span></header><div class="profile-letter__polaroids" :class="{ loading }"><button v-for="(item,index) in slots" :key="item?.id||`empty-${index}`" type="button" :class="{ empty:!item }" :disabled="!item" @click="item&&emit('open-moments')"><template v-if="item"><img :src="item.previewImage" alt="动态照片" loading="lazy"/><span>{{ formatDate(item.time) }}</span></template><i v-else></i></button></div><button class="profile-letter__more" type="button" @click="emit('open-moments')">查看全部记录</button></section>
    </main>
  </section>
</template>

<style scoped>
