ne);font-size:12px}.profile-letter__album>header span:last-child{color:var(--l-muted);font-size:10px}.profile-letter__polaroids{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:16px}.profile-letter__polaroids>button{appearance:none;min-width:0;padding:7px 7px 10px;border:0;background:var(--l-paper);box-shadow:0 6px 16px rgba(0,0,0,.05)}.profile-letter__polaroids>button:nth-child(1){transform:rotate(-1.2deg)}.profile-letter__polaroids>button:nth-child(2){transform:rotate(.6deg)}.profile-letter__polaroids>button:nth-child(3){transform:rotate(-.4deg)}.profile-letter__polaroids img,.profile-letter__polaroids i{display:block;width:100%;aspect-ratio:.86;object-fit:cover;background:#ededeb}.profile-letter__polaroids>button.empty i{border:1px solid var(--l-line);background:linear-gradient(135deg,transparent 49.5%,var(--l-line) 50%,transparent 50.5%),var(--l-paper);opacity:.65}.profile-letter__polaroids span{display:block;margin-top:7px;color:var(--l-muted);font-size:8px;text-align:center}.profile-letter__polaroids.loading button{animation:letter-pulse 1.2s ease-in-out infinite}@keyframes letter-pulse{50%{opacity:.5}}.profile-letter__more{appearance:none;display:block;margin:18px auto 0;padding:7px 0;border:0;border-bottom:1px solid var(--l-line);background:transparent;color:var(--l-muted);font:10px Georgia,"Songti SC",serif}:global(.dark-theme) .profile-letter{--l-bg:#18191a;--l-paper:#222325;--l-text:#ecece8;--l-muted:#939397;--l-line:#303134;background:repeating-linear-gradient(to bottom,transparent 0,transparent 27px,rgba(255,255,255,.018) 28px),var(--l-bg)}:global(.dark-theme) .profile-letter__photo-sheet:before{background:rgba(70,71,73,.88)}:global(.dark-theme) .profile-letter__photo-sheet>div{background:#222325}:global(.dark-theme) .profile-letter__avatar.fallback{background:#353739;color:#bbb}:global(.dark-theme) .profile-letter__polaroids img{background:#303234}
</style>
